-- rpt.vDailyTotal: only in source
GO
CREATE OR ALTER VIEW rpt.vDailyTotal
AS
SELECT CAST(CreatedAt AS date) AS OrderDate, SUM(Amount) AS Total
FROM dbo.Orders
GROUP BY CAST(CreatedAt AS date);

